const texto = $('Vendedor IA').first().json.output || '';
const match = texto.match(/drive\.google\.com\/drive\/folders\/([a-zA-Z0-9_-]+)/);
const folderId = match ? match[1] : '';
const cat = {
  '1VFPtj62RnZEymFnu40BKxPTYG7vL0u7p': 'Artesanal Luxo 15 pares',
  '1A9r9fWed1ZWuC7sMQQgDPkRYdldn6bXC': 'Artesanal 5 pares',
  '1200bA34Qcu3mV2Bcp8nfSrMNXHnSFHpT': 'Kits atacado/revenda',
  '1ExfLDKoYYoMvwaLfbx_qmGLM6-S3NxGN': 'Joias de Unha',
  '1bXs-MYZBWLXqtt-QywggAifgnQdMJ4w0': '3D Cartelas 30 pares'
};
if (!folderId) return [];
return [{ json: { folder_id: folderId, categoria: cat[folderId] || 'Catalogo Unhabella' } }];

const resp = $input.first().json;
const files = resp.files || [];
const cat = $('Code: Extrair Folder ID').first().json.categoria || 'Catalogo Unhabella';
const imagens = files.filter(function(f){ return f.mimeType && f.mimeType.startsWith('image/'); });
if (imagens.length === 0) return [];
return imagens.map(function(f){
  var nome = (f.name || '').replace(/\.[^.]+$/, '');
  return { json: { file_id: f.id, file_name: f.name, mime_type: f.mimeType || 'image/jpeg', caption: cat + ' — ' + nome } };
});

const item = $input.item;
const binaryData = item.binary || {};
const keys = Object.keys(binaryData);
if (keys.length === 0) { return [{ json: { foto_base64: '', caption: '', erro: 'sem binary' } }]; }
const key = keys[0];
const base64 = binaryData[key].data || '';
const mimeType = binaryData[key].mimeType || 'image/jpeg';
let caption = '';
try { caption = $('Code: Preparar URLs Fotos').item.json.caption || ''; } catch(e) {}
return [{ json: { foto_base64: 'data:' + mimeType + ';base64,' + base64, mime_type: mimeType, caption: caption } }];

const texto = $json.output || $json.text || '';
const textoLimpo = texto
  .replace(/https?:\/\/drive\.google\.com\/drive\/folders\/[a-zA-Z0-9_-]+/g, '')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
return [{ json: { output: textoLimpo, output_original: texto } }];

